class Item implements Comparable<Item> {
    int price;
    Item(int price) { this.price = price; }
    public int compareTo(Item other) { return Integer.compare(price, other.price); }
}

TreeSet<Item> set = new TreeSet<>();
Item first = new Item(10);
set.add(first);
set.add(new Item(20));
set.add(new Item(30));
first.price = 99;                 // the comparison field changes
System.out.println(set.contains(first));

